const INDEX=[{"slug": "fact-brief-windrural", "fb": true, "date": "8 September 2026", "words": 338, "topic": "energy", "title": {"en": "Fact brief - Does hosting wind turbines provide farmers with additional income?", "id": "Fakta singkat - Apakah keberadaan turbin angin memberikan penghasilan tambahan bagi petani?"}, "claim": {"id": "Kincir angin merugikan petani karena memakan lahan.", "en": "Wind turbines hurt farmers by taking their land."}, "fakta": {"id": "Sekitar 98% lahan di proyek kincir angin tetap bisa dipakai untuk bertani atau beternak, dan petani mendapat uang sewa tambahan.", "en": "About 98% of land in a wind project stays available for farming or grazing, and farmers earn extra lease income."}, "question": {"en": "Does hosting wind turbines provide farmers with additional income?", "id": "Apakah keberadaan turbin angin memberikan penghasilan tambahan bagi petani?"}, "kw": "kincir angin petani sewa lahan", "thumb": null}, {"slug": "fact-brief-windco2", "fb": true, "date": "25 August 2026", "words": 344, "topic": "energy", "title": {"en": "Fact brief - Do wind turbines release more emissions than burning fossil fuels?", "id": "Fakta singkat - Apakah turbin angin melepaskan lebih banyak emisi dibandingkan bahan bakar fosil?"}, "claim": {"id": "Kincir angin menghasilkan emisi lebih banyak daripada batu bara.", "en": "Wind turbines cause more emissions than coal."}, "fakta": {"id": "Kincir angin memang menghasilkan sedikit emisi saat dibuat dan dikirim. Tapi untuk listrik yang sama, batu bara menghasilkan sekitar 77 kali lebih banyak.", "en": "Turbines cause some emissions when built and shipped, but for the same electricity coal emits about 77 times more."}, "question": {"en": "Do wind turbines release more emissions than burning fossil fuels?", "id": "Apakah turbin angin mengeluarkan lebih banyak emisi dibandingkan pembakaran bahan bakar fosil?"}, "kw": "kincir angin pltb bayu emisi", "thumb": null}, {"slug": "fact-brief-solarmineral", "fb": true, "date": "11 August 2026", "words": 431, "topic": "energy", "title": {"en": "Fact brief - Are there enough minerals for solar power expansion to help mitigate climate change?", "id": "Fakta singkat - Apakah terdapat cukup mineral untuk perluasan tenaga surya guna membantu mitigasi perubahan iklim?"}, "claim": {"id": "Bahan tambang di dunia tidak cukup untuk membuat banyak panel surya.", "en": "There aren't enough minerals to build lots of solar panels."}, "fakta": {"id": "Menurut penelitian tahun 2023, persediaan mineral yang sudah diketahui cukup. Tantangannya ada pada produksi dan pengiriman, bukan kekurangan bahan.", "en": "A 2023 study found known mineral supplies are enough. The challenge is production and supply chains, not shortages."}, "question": {"en": "Are there enough minerals for solar power expansion to help mitigate climate change?", "id": "Apakah terdapat cukup mineral untuk perluasan tenaga surya guna membantu mitigasi perubahan iklim?"}, "kw": "panel surya tambang mineral", "thumb": null}, {"slug": "fact-brief-solarunrel", "fb": true, "date": "28 July 2026", "words": 393, "topic": "energy", "title": {"en": "Fact brief - Do solar plants require backup from fossil fuels?", "id": "Fakta singkat - Apakah pembangkit listrik tenaga surya memerlukan cadangan bahan bakar fosil?"}, "claim": {"id": "Tenaga surya selalu butuh cadangan dari batu bara atau gas.", "en": "Solar power always needs coal or gas backup."}, "fakta": {"id": "Tenaga surya memang butuh cadangan, tapi cadangannya bisa dari baterai, angin, dan kiriman listrik dari daerah lain.", "en": "Solar does need backup, but it can come from batteries, wind and power sent from other regions."}, "question": {"en": "Do solar plants require backup from fossil fuels?", "id": "Apakah pembangkit listrik tenaga surya memerlukan cadangan bahan bakar fosil?"}, "kw": "panel surya cadangan baterai", "thumb": null}, {"slug": "fact-brief-evweather", "fb": true, "date": "14 July 2026", "words": 382, "topic": "energy", "title": {"en": "Fact brief - Do electric vehicles stop working in extreme heat?", "id": "Fakta singkat - Apakah kendaraan listrik berhenti bekerja dalam cuaca yang sangat panas?"}, "claim": {"id": "Mobil listrik mogok kalau cuaca sangat panas.", "en": "Electric cars stop working in extreme heat."}, "fakta": {"id": "Panas ekstrem hanya mengurangi jarak tempuh sedikit, sekitar 14% pada suhu 35°C. Mobil bensin juga turun dengan persentase yang sama. Mobil listrik tetap bisa jalan.", "en": "Extreme heat cuts range a little, about 14% at 35°C, the same share as petrol cars. EVs keep working."}, "question": {"en": "Do electric vehicles stop working in extreme heat?", "id": "Apakah kendaraan listrik berhenti bekerja dalam cuaca yang sangat panas?"}, "kw": "mobil listrik panas mogok", "thumb": null}, {"slug": "fact-brief-windfall", "fb": true, "date": "30 June 2026", "words": 390, "topic": "energy", "title": {"en": "Fact brief - Are injuries from wind turbines common?", "id": "Fakta singkat - Apakah cedera akibat turbin angin sering terjadi?"}, "claim": {"id": "Kecelakaan akibat kincir angin sering terjadi.", "en": "Injuries from wind turbines are common."}, "fakta": {"id": "Kincir angin roboh atau baling-balingnya patah sangat jarang terjadi. Untuk listrik yang sama, tenaga angin jauh lebih sedikit menyebabkan kematian daripada bahan bakar fosil.", "en": "Turbine collapses and blade failures are very rare, and wind causes far fewer deaths per unit of electricity than fossil fuels."}, "question": {"en": "Are injuries from wind turbines common?", "id": "Apakah cedera akibat turbin angin sering terjadi?"}, "kw": "kincir angin kecelakaan roboh", "thumb": null}, {"slug": "fact-brief-solarprice", "fb": true, "date": "16 June 2026", "words": 342, "topic": "energy", "title": {"en": "Fact brief - Does solar energy need subsidies to compete with fossil fuels?", "id": "Fakta singkat – Apakah energi surya memerlukan subsidi untuk bersaing dengan bahan bakar fosil?"}, "claim": {"id": "Tenaga surya hanya bisa bersaing kalau disubsidi pemerintah.", "en": "Solar only competes with fossil fuels because of subsidies."}, "fakta": {"id": "Tanpa subsidi pun, pembangkit tenaga surya besar sekarang umumnya lebih murah daripada membangun pembangkit batu bara atau gas baru.", "en": "Even without subsidies, large solar farms are now generally cheaper than new coal or gas plants."}, "question": {"en": "Does solar energy need subsidies to compete with fossil fuels?", "id": "Apakah energi surya memerlukan subsidi untuk bersaing dengan bahan bakar fosil?"}, "kw": "panel surya subsidi murah harga", "thumb": null}, {"slug": "fact-brief-evharm", "fb": true, "date": "2 June 2026", "words": 373, "topic": "energy", "title": {"en": "Fact brief - Do electric vehicles almost always have a lower carbon footprint than gasoline-powered cars?", "id": "Fakta singkat - Apakah kendaraan listrik hampir selalu memiliki jejak karbon yang lebih rendah dibandingkan mobil bertenaga bensin?"}, "claim": {"id": "Mobil listrik lebih mencemari daripada mobil bensin.", "en": "Electric cars pollute more than petrol cars."}, "fakta": {"id": "Kalau dihitung dari pembuatan sampai pemakaian, mobil listrik hampir selalu menghasilkan emisi gas rumah kaca lebih sedikit daripada mobil bensin.", "en": "Counting from manufacture to use, electric cars almost always produce fewer emissions than petrol cars."}, "question": {"en": "Do electric vehicles almost always have a lower carbon footprint than gasoline-powered cars?", "id": "Apakah kendaraan listrik hampir selalu memiliki jejak karbon yang lebih rendah dibandingkan mobil bertenaga bensin?"}, "kw": "mobil listrik motor listrik ev baterai kendaraan", "thumb": null}, {"slug": "fact-brief-windem", "fb": true, "date": "19 May 2026", "words": 369, "topic": "energy", "title": {"en": "Fact brief - Does electromagnetic radiation from wind turbines pose a threat to human health?", "id": "Fakta singkat - Apakah radiasi elektromagnetik dari turbin angin menimbulkan ancaman bagi kesehatan manusia?"}, "claim": {"id": "Radiasi dari kincir angin berbahaya bagi kesehatan.", "en": "Radiation from wind turbines harms health."}, "fakta": {"id": "Medan elektromagnetik dari kincir angin jauh di bawah batas aman, bahkan lebih lemah daripada dari microwave atau penyedot debu di rumah.", "en": "Wind turbine electromagnetic fields are far below safety limits, weaker than from a microwave or vacuum cleaner."}, "question": {"en": "Does electromagnetic radiation from wind turbines pose a threat to human health?", "id": "Apakah radiasi elektromagnetik dari turbin angin menimbulkan ancaman bagi kesehatan manusia?"}, "kw": "kincir angin radiasi gelombang", "thumb": null}, {"slug": "fact-brief-windwhales", "fb": true, "date": "4 May 2026", "words": 423, "topic": "energy", "title": {"en": "Fact brief - Were the 2022 whale deaths off the US East Coast caused by offshore wind development?", "id": "Fakta singkat - Apakah kematian paus pada tahun 2022 di lepas pantai Timur AS disebabkan oleh perkembangan angin lepas pantai?"}, "claim": {"id": "Paus mati di pantai Amerika tahun 2022 karena proyek kincir angin di laut.", "en": "Offshore wind caused the 2022 whale deaths off the US coast."}, "fakta": {"id": "Penelitian tidak menemukan bukti bahwa kincir angin laut menyebabkan kematian paus itu. Aturan pembangunan juga dibuat untuk melindungi paus.", "en": "Research found no evidence linking offshore wind to those deaths, and construction rules are in place to protect whales."}, "question": {"en": "Were the 2022 whale deaths off the US East Coast caused by offshore wind development?", "id": "Apakah kematian paus pada tahun 2022 di lepas pantai Timur AS disebabkan oleh pengembangan angin lepas pantai?"}, "kw": "kincir angin laut paus", "thumb": null}, {"slug": "fact-brief-windland", "fb": true, "date": "7 April 2026", "words": 405, "topic": "energy", "title": {"en": "Fact brief - Do wind turbines utilize land for electricity generation more efficiently than fossil fuels?", "id": "Fakta singkat - Apakah turbin angin memanfaatkan lahan untuk menghasilkan listrik lebih efisien dibandingkan bahan bakar fosil?"}, "claim": {"id": "Kincir angin memakan lahan lebih banyak daripada minyak dan gas.", "en": "Wind farms use more land than oil and gas."}, "fakta": {"id": "Untuk listrik yang sama, kincir angin butuh lahan lebih sedikit, dan lahan di antara kincir tetap bisa dipakai untuk bertani.", "en": "For the same energy, wind uses less land, and land between turbines can still be farmed."}, "question": {"en": "Do wind turbines utilize land for electricity generation more efficiently than fossil fuels?", "id": "Apakah turbin angin memanfaatkan lahan untuk menghasilkan listrik lebih efisien dibandingkan bahan bakar fosil?"}, "kw": "kincir angin pltb lahan", "thumb": null}, {"slug": "fact-brief-windsyndrome", "fb": true, "date": "24 March 2026", "words": 427, "topic": "energy", "title": {"en": "Fact brief - Is 'wind-turbine syndrome' a medically recognized diagnosis?", "id": "Fakta singkat - Apakah 'sindrom turbin angin' merupakan diagnosis yang diakui secara medis?"}, "claim": {"id": "Ada penyakit khusus bernama sindrom kincir angin.", "en": "'Wind turbine syndrome' is a real illness."}, "fakta": {"id": "Tidak ada organisasi kedokteran yang mengakui penyakit ini. Penelitian tidak menemukan hubungan jelas antara suara kincir angin dan penyakit tertentu.", "en": "No medical organisation recognises it, and research finds no clear link between turbine sound and any specific illness."}, "question": {"en": "Is 'wind-turbine syndrome' a medically recognized diagnosis?", "id": "Apakah 'sindrom turbin angin' merupakan diagnosis yang diakui secara medis?"}, "kw": "kincir angin suara sakit", "thumb": null}, {"slug": "fact-brief-windshadow", "fb": true, "date": "10 March 2026", "words": 362, "topic": "energy", "title": {"en": "Fact brief - Can shadow flicker from wind turbines trigger seizures in people with epilepsy?", "id": "Fakta singkat - Bisakah kedipan bayangan dari turbin angin memicu kejang pada penderita epilepsi?"}, "claim": {"id": "Bayangan kincir angin yang berkedip bisa memicu kejang pada penderita epilepsi.", "en": "Shadow flicker from wind turbines triggers epileptic seizures."}, "fakta": {"id": "Kedipan bayangan kincir angin terlalu lambat, sekitar 0,5 sampai 1 kali per detik. Kejang karena cahaya biasanya baru terpicu pada 3 kedipan per detik atau lebih.", "en": "Turbine flicker is too slow, about 0.5 to 1 per second. Light-triggered seizures usually need 3 flashes per second or more."}, "question": {"en": "Can shadow flicker from wind turbines trigger seizures in people with epilepsy?", "id": "Bisakah kedipan bayangan dari turbin angin memicu kejang pada penderita epilepsi?"}, "kw": "kincir angin bayangan epilepsi kejang", "thumb": null}, {"slug": "fact-brief-solarclouds", "fb": true, "date": "24 February 2026", "words": 402, "topic": "energy", "title": {"en": "Fact brief - Do solar panels work in cold or cloudy climates?", "id": "Fakta singkat - Apakah panel surya berfungsi di iklim dingin atau berawan?"}, "claim": {"id": "Panel surya tidak menghasilkan listrik kalau cuaca mendung.", "en": "Solar panels don't work when it's cloudy."}, "fakta": {"id": "Panel surya tetap menghasilkan listrik saat mendung, hanya lebih sedikit.", "en": "Solar panels still make electricity on cloudy days, just less."}, "question": {"en": "Do solar panels work in cold or cloudy climates?", "id": "Apakah panel surya berfungsi di iklim dingin atau berawan?"}, "kw": "panel surya plts mendung hujan awan solar", "thumb": null}, {"slug": "fact-brief-solarhomeval", "fb": true, "date": "10 February 2026", "words": 425, "topic": "energy", "title": {"en": "Fact brief - Can nearby solar farms reduce property values?", "id": "Fakta singkat - Bisakah pembangkit listrik tenaga surya di dekatnya mengurangi nilai properti?"}, "claim": {"id": "Ladang panel surya membuat harga rumah di sekitarnya anjlok.", "en": "Solar farms make nearby house prices crash."}, "fakta": {"id": "Harga rumah yang sangat dekat bisa turun sedikit, sekitar 1,5%. Dampaknya lebih kecil daripada tinggal dekat pembangkit batu bara atau gas.", "en": "Homes very close by may lose a little value, about 1.5%, less than near coal or gas plants."}, "question": {"en": "Can nearby solar farms reduce property values?", "id": "Bisakah pembangkit listrik tenaga surya di dekatnya mengurangi nilai properti?"}, "kw": "panel surya harga rumah tanah", "thumb": null}, {"slug": "fact-brief-solarbiodiv", "fb": true, "date": "3 February 2026", "words": 365, "topic": "energy", "title": {"en": "Fact brief - Can solar projects improve biodiversity?", "id": "Fakta singkat - Dapatkah proyek tenaga surya meningkatkan keanekaragaman hayati?"}, "claim": {"id": "Panel surya pasti merusak alam dan satwa.", "en": "Solar farms always harm nature and wildlife."}, "fakta": {"id": "Kalau dibangun dengan cara yang baik, lahan panel surya bisa menjaga, bahkan menambah, tanaman, serangga, dan burung.", "en": "Built well, solar sites can keep or even increase plants, insects and birds."}, "question": {"en": "Can solar projects improve biodiversity?", "id": "Dapatkah proyek tenaga surya meningkatkan keanekaragaman hayati?"}, "kw": "panel surya satwa burung alam", "thumb": null}, {"slug": "fact-brief-solarag", "fb": true, "date": "27 January 2026", "words": 380, "topic": "energy", "title": {"en": "Fact brief - Are solar projects hurting farmers and rural communities?", "id": "Fakta singkat - Apakah proyek tenaga surya merugikan petani dan masyarakat pedesaan?"}, "claim": {"id": "Panel surya merugikan petani dan warga desa.", "en": "Solar projects hurt farmers and rural communities."}, "fakta": {"id": "Panel surya bisa dipasang bersama pertanian. Naungannya membantu tanaman dan ternak, dan bisa menambah penghasilan petani.", "en": "Solar can share land with farming. The shade helps crops and animals and can raise farm income."}, "question": {"en": "Are solar projects hurting farmers and rural communities?", "id": "Apakah proyek tenaga surya merugikan petani dan masyarakat pedesaan?"}, "kw": "panel surya petani sawah desa", "thumb": null}, {"slug": "fact-brief-solarvsff", "fb": true, "date": "20 January 2026", "words": 339, "topic": "energy", "title": {"en": "Fact brief - Do solar panels release more emissions than burning fossil fuels?", "id": "Fakta singkat - Apakah panel surya mengeluarkan lebih banyak emisi dibandingkan pembakaran bahan bakar fosil?"}, "claim": {"id": "Panel surya menghasilkan emisi lebih banyak daripada batu bara.", "en": "Solar panels cause more emissions than coal."}, "fakta": {"id": "Panel surya memang menghasilkan sedikit emisi saat dibuat dan dikirim, tapi totalnya jauh lebih kecil daripada batu bara atau gas.", "en": "Making and shipping solar panels does cause some emissions, but the total is far lower than coal or gas."}, "question": {"en": "Do solar panels release more emissions than burning fossil fuels?", "id": "Apakah panel surya mengeluarkan lebih banyak emisi dibandingkan pembakaran bahan bakar fosil?"}, "kw": "panel surya plts emisi batu bara solar", "thumb": null}, {"slug": "fact-brief-solartrees", "fb": true, "date": "13 January 2026", "words": 388, "topic": "energy", "title": {"en": "Fact brief - Does clearing trees for solar panels release more CO2 than the solar panels would prevent?", "id": "Fakta singkat - Apakah menebang pohon untuk panel surya melepaskan lebih banyak CO2 daripada yang dapat dicegah oleh panel surya?"}, "claim": {"id": "Menebang pohon untuk panel surya melepas lebih banyak CO2 daripada yang dicegah panel itu.", "en": "Clearing trees for solar releases more CO2 than the panels save."}, "fakta": {"id": "Panel surya di satu lahan mencegah sekitar 200 kali lebih banyak CO2 daripada yang diserap hutan seluas yang sama setiap tahun.", "en": "Solar on a piece of land prevents about 200 times more CO2 each year than the same area of forest absorbs."}, "question": {"en": "Does clearing trees for solar panels release more CO2 than the solar panels would prevent?", "id": "Apakah menebang pohon untuk panel surya melepaskan lebih banyak CO2 daripada yang dapat dicegah oleh panel surya?"}, "kw": "panel surya pohon hutan tebang", "thumb": null}, {"slug": "fact-brief-solarwaste", "fb": true, "date": "23 December 2025", "words": 388, "topic": "energy", "title": {"en": "Fact brief - Do solar panels generate more waste than fossil fuels?", "id": "Fakta singkat - Apakah panel surya menghasilkan lebih banyak limbah dibandingkan bahan bakar fosil?"}, "claim": {"id": "Panel surya menghasilkan sampah lebih banyak daripada bahan bakar fosil.", "en": "Solar panels create more waste than fossil fuels."}, "fakta": {"id": "Sampah dari batu bara, minyak, dan gas jauh lebih banyak. Abu batu bara bisa 300 sampai 800 kali lebih berat daripada sampah panel surya.", "en": "Fossil fuel waste is far larger. Coal ash can weigh 300 to 800 times more than discarded solar panels."}, "question": {"en": "Do solar panels generate more waste than fossil fuels?", "id": "Apakah panel surya menghasilkan lebih banyak limbah dibandingkan bahan bakar fosil?"}, "kw": "panel surya sampah limbah", "thumb": null}, {"slug": "fact-brief-solarmetals", "fb": true, "date": "16 December 2025", "words": 335, "topic": "energy", "title": {"en": "Fact brief - Are toxic heavy metals from solar panels posing a threat to human health?", "id": "Fakta singkat - Apakah logam berat beracun dari panel surya mengancam kesehatan manusia?"}, "claim": {"id": "Logam berat di panel surya meracuni manusia.", "en": "Heavy metals in solar panels poison people."}, "fakta": {"id": "Logam di panel surya terkunci dalam bahan yang stabil dan tertutup kaca tebal, jadi tidak lepas ke udara, air, atau tanah dalam jumlah berbahaya.", "en": "The metals are locked in stable compounds behind tough glass, so they don't escape at harmful levels."}, "question": {"en": "Are toxic heavy metals from solar panels posing a threat to human health?", "id": "Apakah logam berat beracun dari panel surya mengancam kesehatan manusia?"}, "kw": "panel surya racun logam", "thumb": null}, {"slug": "fact-brief-solaremf", "fb": true, "date": "9 December 2025", "words": 358, "topic": "energy", "title": {"en": "Fact brief - Are electromagnetic fields from solar farms harmful to human health?", "id": "Fakta singkat - Apakah medan elektromagnetik dari pembangkit listrik tenaga surya berbahaya bagi kesehatan manusia?"}, "claim": {"id": "Medan listrik dari ladang panel surya berbahaya bagi kesehatan.", "en": "Electromagnetic fields from solar farms are harmful."}, "fakta": {"id": "Medan elektromagnetik dari panel surya sangat lemah, jauh di bawah batas aman, bahkan lebih lemah daripada gelombang radio.", "en": "Solar farm fields are very weak, well within safety limits, and weaker than radio waves."}, "question": {"en": "Are electromagnetic fields from solar farms harmful to human health?", "id": "Apakah medan elektromagnetik dari pembangkit listrik tenaga surya berbahaya bagi kesehatan manusia?"}, "kw": "panel surya radiasi gelombang", "thumb": null}, {"slug": "fact-brief-arcticcycle-2", "fb": true, "date": "2 December 2025", "words": 352, "topic": "ocean", "title": {"en": "Fact brief - Does the recent slowdown in Arctic sea-ice extent loss disprove human-caused warming?", "id": "Fakta singkat - Apakah penurunan luas es di laut Arktik yang terjadi baru-baru ini menyangkal pemanasan yang disebabkan oleh aktivitas manusia?"}, "claim": {"id": "Es laut Arktik berhenti mencair, jadi pemanasan global itu bohong.", "en": "Arctic sea ice has stopped melting, so global warming is fake."}, "fakta": {"id": "Perlambatan sebentar itu hanya naik-turun alami. Dalam puluhan tahun, es laut Arktik terus berkurang.", "en": "A short slowdown is natural ups and downs. Over decades, Arctic sea ice keeps shrinking."}, "question": {"en": "Does the recent slowdown in Arctic sea-ice extent loss disprove human-caused warming?", "id": "Apakah perlambatan hilangnya luas es di lautan Arktik baru-baru ini menyangkal pemanasan yang disebabkan oleh aktivitas manusia?"}, "kw": "es arktik kutub", "thumb": null}, {"slug": "fact-brief-sun-2", "fb": true, "date": "21 November 2025", "words": 334, "topic": "cause", "title": {"en": "Fact brief - Are changes in solar activity causing climate change?", "id": "Fakta singkat - Apakah perubahan aktivitas matahari menyebabkan perubahan iklim?"}, "claim": {"id": "Bumi makin panas karena matahari makin terik.", "en": "Earth is warming because the Sun is getting stronger."}, "fakta": {"id": "Bukan. Sejak akhir 1970-an, energi dari matahari justru sedikit turun, sementara Bumi terus memanas.", "en": "No. Since the late 1970s the Sun's energy has dipped slightly, while Earth kept warming."}, "question": {"en": "Are changes in solar activity causing climate change?", "id": "Apakah perubahan aktivitas matahari menyebabkan perubahan iklim?"}, "kw": "matahari surya terik sun bintik", "thumb": null}, {"slug": "fact-brief-cold", "fb": true, "date": "4 November 2025", "words": 317, "topic": "warm", "title": {"en": "Fact brief - Does cold weather disprove human-caused climate change", "id": "Fakta singkat - Apakah cuaca dingin menyangkal perubahan iklim yang disebabkan oleh manusia"}, "claim": {"id": "Kalau masih ada cuaca dingin, berarti Bumi tidak memanas.", "en": "If it still gets cold, Earth isn't warming."}, "fakta": {"id": "Cuaca dingin sesekali tetap bisa terjadi. Tapi kalau dilihat per tahun, suhu Bumi terus naik. Cuaca itu hari ini, iklim itu puluhan tahun.", "en": "Cold spells still happen. But year after year, Earth keeps getting warmer. Weather is today; climate is decades."}, "question": {"en": "Does cold weather disprove human-caused climate change", "id": "Apakah cuaca dingin menyangkal perubahan iklim yang disebabkan oleh manusia?"}, "kw": "dingin salju es cuaca dingin cold winter", "thumb": null}, {"slug": "fact-brief-evidence", "fb": true, "date": "28 October 2025", "words": 338, "topic": "warm", "title": {"en": "Fact brief - Is there empirical evidence for human-caused global warming?", "id": "Fakta singkat - Apakah ada bukti empiris mengenai pemanasan global yang disebabkan oleh aktivitas manusia?"}, "claim": {"id": "Tidak ada bukti bahwa manusia membuat Bumi makin panas.", "en": "There's no evidence people are warming the planet."}, "fakta": {"id": "Ada banyak bukti dari berbagai pengukuran bahwa gas buang dari kegiatan manusia membuat Bumi memanas.", "en": "Many different measurements show that our emissions are warming the planet."}, "question": {"en": "Is there empirical evidence for human-caused global warming?", "id": "Apakah ada bukti empiris mengenai pemanasan global yang disebabkan oleh manusia?"}, "kw": "bukti manusia rumah kaca", "thumb": null}, {"slug": "fact-brief-greenhouse", "fb": true, "date": "14 October 2025", "words": 368, "topic": "cause", "title": {"en": "Fact brief - Does increasing CO2 have a noticeable effect?", "id": "Fakta singkat - Apakah peningkatan CO2 mempunyai dampak yang nyata?"}, "claim": {"id": "Tambahan CO2 di udara tidak berpengaruh pada suhu.", "en": "Extra CO2 in the air makes no difference."}, "fakta": {"id": "Sudah dibuktikan sejak tahun 1800-an bahwa CO2 menahan panas. Makin banyak CO2, Bumi makin hangat.", "en": "It has been proven since the 1800s that CO2 traps heat. More CO2 means a warmer Earth."}, "question": {"en": "Does increasing CO2 have a noticeable effect?", "id": "Apakah peningkatan CO2 mempunyai dampak yang nyata?"}, "kw": "co2 karbon rumah kaca pengaruh", "thumb": null}, {"slug": "fact-brief-gore", "fb": true, "date": "7 October 2025", "words": 392, "topic": "hoax", "title": {"en": "Fact brief - Do errors in Al Gore's 'An Inconvenient Truth' disprove climate change?", "id": "Fakta singkat - Apakah kesalahan dalam 'An Inconvenient Truth' karya Al Gore menyangkal perubahan iklim?"}, "claim": {"id": "Ada kesalahan di film Al Gore, jadi perubahan iklim itu bohong.", "en": "Errors in Al Gore's film prove climate change is fake."}, "fakta": {"id": "Beberapa perkiraan di film tahun 2006 itu memang keliru, tapi puluhan tahun penelitian tetap membuktikan bahwa manusia memanaskan Bumi.", "en": "Some predictions in the 2006 film were wrong, but decades of research still show humans are warming the planet."}, "question": {"en": "Do errors in Al Gore's 'An Inconvenient Truth' disprove climate change?", "id": "Apakah kesalahan dalam 'An Inconvenient Truth' karya Al Gore menyangkal perubahan iklim?"}, "kw": "al gore film", "thumb": null}, {"slug": "fact-brief-agw", "fb": true, "date": "30 September 2025", "words": 362, "topic": "cause", "title": {"en": "Fact brief - Are humans responsible for climate change?", "id": "Fakta singkat - Apakah manusia bertanggung jawab atas perubahan iklim?"}, "claim": {"id": "Perubahan iklim terjadi dengan sendirinya, bukan karena manusia.", "en": "Climate change happens by itself, not because of people."}, "fakta": {"id": "Manusia penyebabnya. Membakar batu bara, minyak, dan gas melepas CO2 yang menumpuk di udara dan menahan panas.", "en": "People are the cause. Burning coal, oil and gas releases CO2 that builds up in the air and traps heat."}, "question": {"en": "Are humans responsible for climate change?", "id": "Apakah manusia bertanggung jawab atas perubahan iklim?"}, "kw": "manusia penyebab alami", "thumb": null}, {"slug": "fact-brief-underestimate", "fb": true, "date": "23 September 2025", "words": 336, "topic": "hoax", "title": {"en": "Fact brief - Has the IPCC overestimated climate change impacts?", "id": "Fakta singkat - Apakah IPCC melebih-lebihkan dampak perubahan iklim?"}, "claim": {"id": "IPCC melebih-lebihkan dampak perubahan iklim.", "en": "The IPCC exaggerates climate impacts."}, "fakta": {"id": "Justru banyak perkiraan IPCC terlalu hati-hati. Contohnya, kenaikan permukaan laut ternyata lebih cepat dari perkiraan lama.", "en": "Many IPCC estimates were too cautious. Sea level rise, for example, has been faster than older reports expected."}, "question": {"en": "Has the IPCC overestimated climate change impacts?", "id": "Apakah IPCC melebih-lebihkan dampak perubahan iklim?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-falsify", "fb": true, "date": "16 September 2025", "words": 323, "topic": "hoax", "title": {"en": "Fact brief - Has the greenhouse effect been falsified?", "id": "Fakta singkat – Apakah efek rumah kaca telah dipalsukan?"}, "claim": {"id": "Efek rumah kaca sudah terbukti salah.", "en": "The greenhouse effect has been disproved."}, "fakta": {"id": "Efek rumah kaca adalah ilmu dasar yang sudah dikenal hampir 200 tahun. Tanpa efek ini, Bumi terlalu dingin untuk kehidupan.", "en": "The greenhouse effect is basic physics known for almost 200 years. Without it, Earth would be too cold for life."}, "question": {"en": "Has the greenhouse effect been falsified?", "id": "Apakah efek rumah kaca telah dipalsukan?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-arctic", "fb": true, "date": "9 September 2025", "words": 328, "topic": "ocean", "title": {"en": "Fact brief - Has Arctic sea ice recovered?", "id": "Fakta singkat - Apakah es laut Arktik sudah pulih?"}, "claim": {"id": "Es laut Arktik sudah pulih.", "en": "Arctic sea ice has recovered."}, "fakta": {"id": "Es laut Arktik terus berkurang, baik luas maupun ketebalannya. Maret 2025 mencatat luas maksimum terendah.", "en": "Arctic sea ice keeps shrinking in area and thickness. March 2025 set a record-low maximum."}, "question": {"en": "Has Arctic sea ice recovered?", "id": "Apakah es laut Arktik sudah pulih?"}, "kw": "es arktik kutub", "thumb": null}, {"slug": "fact-brief-warming", "fb": true, "date": "2 September 2025", "words": 338, "topic": "warm", "title": {"en": "Fact brief - Is global warming actually happening?", "id": "Fakta singkat – Apakah pemanasan global benar-benar terjadi?"}, "claim": {"id": "Pemanasan global itu tidak nyata.", "en": "Global warming isn't real."}, "fakta": {"id": "Bumi memang makin panas. Suhunya sekarang hampir 1,5°C lebih tinggi daripada abad ke-19, dan 10 tahun terakhir adalah yang terpanas sejak dicatat.", "en": "Earth really is warming. It is now almost 1.5°C warmer than in the 19th century, and the last 10 years were the hottest on record."}, "question": {"en": "Is global warming actually happening?", "id": "Apakah pemanasan global benar-benar terjadi?"}, "kw": "pemanasan global nyata hoaks bohong", "thumb": null}, {"slug": "fact-brief-temp", "fb": true, "date": "22 August 2025", "words": 365, "topic": "warm", "title": {"en": "Fact brief - Are surface temperature records reliable?", "id": "Fakta singkat - Apakah catatan suhu permukaan dapat diandalkan?"}, "claim": {"id": "Catatan suhu Bumi tidak bisa dipercaya.", "en": "Temperature records can't be trusted."}, "fakta": {"id": "Suhu dicatat oleh lebih dari 30.000 stasiun dan sudah diperiksa oleh banyak tim yang berbeda. Hasilnya sama: Bumi memanas.", "en": "Temperatures come from more than 30,000 stations and have been checked by many separate teams. They agree: Earth is warming."}, "question": {"en": "Are surface temperature records reliable?", "id": "Apakah catatan suhu permukaan dapat dipercaya?"}, "kw": "data suhu stasiun catatan dipercaya termometer", "thumb": null}, {"slug": "fact-brief-settled", "fb": true, "date": "29 July 2025", "words": 360, "topic": "hoax", "title": {"en": "Fact brief - Is the greenhouse effect still debated among climate scientists?", "id": "Fakta singkat - Apakah efek rumah kaca masih diperdebatkan di kalangan ilmuwan iklim?"}, "claim": {"id": "Para ilmuwan masih berdebat soal efek rumah kaca.", "en": "Scientists are still arguing about the greenhouse effect."}, "fakta": {"id": "Ilmuwan sudah sepakat soal efek rumah kaca sejak lebih dari 100 tahun lalu.", "en": "Scientists have agreed on the greenhouse effect for more than 100 years."}, "question": {"en": "Is the greenhouse effect still debated among climate scientists?", "id": "Apakah efek rumah kaca masih diperdebatkan di kalangan ilmuwan iklim?"}, "kw": "debat ilmuwan sepakat rumah kaca", "thumb": null}, {"slug": "fact-brief-money", "fb": true, "date": "22 July 2025", "words": 375, "topic": "hoax", "title": {"en": "Fact brief - Is climate science a high-paying profession?", "id": "Fakta singkat - Apakah ilmu iklim merupakan profesi bergaji tinggi?"}, "claim": {"id": "Ilmuwan iklim cuma cari uang.", "en": "Climate scientists are only in it for the money."}, "fakta": {"id": "Dana penelitian dipakai untuk alat, data, dan gaji seluruh tim. Gaji ilmuwan iklim biasa saja dibanding banyak pekerjaan lain.", "en": "Research grants pay for equipment, data and whole teams. Climate scientists' pay is ordinary compared with many other jobs."}, "question": {"en": "Is climate science a high-paying profession?", "id": "Apakah ilmu iklim merupakan profesi bergaji tinggi?"}, "kw": "uang gaji dibayar proyek bisnis dana", "thumb": null}, {"slug": "fact-brief-pre1940", "fb": true, "date": "15 July 2025", "words": 342, "topic": "cause", "title": {"en": "Fact brief - Did CO2 contribute to early 20th century warming?", "id": "Fakta singkat - Apakah CO2 berkontribusi terhadap pemanasan awal abad ke-20?"}, "claim": {"id": "Pemanasan tahun 1920 sampai 1940 membuktikan CO2 tidak berpengaruh.", "en": "Warming in 1920 to 1940 proves CO2 doesn't matter."}, "fakta": {"id": "Pemanasan saat itu disebabkan gabungan faktor alam dan CO2 dari manusia, yang mulai naik sejak Revolusi Industri.", "en": "That warming came from a mix of natural factors and human CO2, which had been rising since the Industrial Revolution."}, "question": {"en": "Did CO2 contribute to early 20th century warming?", "id": "Apakah CO2 berkontribusi terhadap pemanasan awal abad ke-20?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-elnino", "fb": true, "date": "8 July 2025", "words": 351, "topic": "elnino", "title": {"en": "Fact brief - Is global warming just due to El Niño?", "id": "Fakta singkat - Apakah pemanasan global hanya disebabkan oleh El Niño?"}, "claim": {"id": "Pemanasan global cuma gara-gara El Niño.", "en": "Global warming is just El Niño."}, "fakta": {"id": "El Niño datang dan pergi setiap beberapa tahun. Ia tidak bisa menjelaskan suhu Bumi yang naik terus selama puluhan tahun.", "en": "El Niño comes and goes every few years. It can't explain decades of steady warming."}, "question": {"en": "Is global warming just due to El Niño?", "id": "Apakah pemanasan global hanya disebabkan oleh El Niño?"}, "kw": "el nino la nina alami siklus", "thumb": null}, {"slug": "fact-brief-driver", "fb": true, "date": "1 July 2025", "words": 332, "topic": "cause", "title": {"en": "Fact brief - Are human CO2 emissions driving current global warming?", "id": "Fakta singkat - Apakah emisi CO2 yang dihasilkan manusia menyebabkan pemanasan global saat ini?"}, "claim": {"id": "Pemanasan sekarang disebabkan faktor alam.", "en": "Today's warming is caused by natural factors."}, "fakta": {"id": "Alam memang memengaruhi iklim, tapi perubahan alami seperti orbit Bumi butuh puluhan ribu tahun. Pemanasan yang cepat sekarang terutama karena CO2 dari manusia.", "en": "Nature does affect climate, but natural changes like Earth's orbit take tens of thousands of years. Today's fast warming is mainly from human CO2."}, "question": {"en": "Are human CO2 emissions driving current global warming?", "id": "Apakah emisi CO2 yang dihasilkan manusia menyebabkan pemanasan global saat ini?"}, "kw": "alam alami penyebab co2 manusia", "thumb": null}, {"slug": "fact-brief-lia", "fb": true, "date": "21 June 2025", "words": 367, "topic": "cause", "title": {"en": "Fact brief - Is modern warming just a rebound from the Little Ice Age?", "id": "Fakta singkat - Apakah pemanasan modern hanyalah dampak dari Zaman Es Kecil?"}, "claim": {"id": "Bumi sekarang cuma kembali hangat setelah Zaman Es Kecil.", "en": "Earth is just recovering from the Little Ice Age."}, "fakta": {"id": "Bumi sekarang lebih panas daripada sebelum Zaman Es Kecil. Jadi ini bukan sekadar pulih, tapi panas baru dari kegiatan manusia.", "en": "Earth is now warmer than before the Little Ice Age. This is new heat from human activity, not a rebound."}, "question": {"en": "Is modern warming just a rebound from the Little Ice Age?", "id": "Apakah pemanasan modern hanyalah dampak dari Zaman Es Kecil?"}, "kw": "zaman es kecil alami siklus pulih", "thumb": null}, {"slug": "fact-brief-1934", "fb": true, "date": "14 June 2025", "words": 331, "topic": "warm", "title": {"en": "Fact brief - Was 1934 the hottest year in the global record?", "id": "Fakta singkat - Apakah tahun 1934 merupakan tahun terpanas dalam rekor global?"}, "claim": {"id": "Tahun 1934 adalah tahun terpanas di dunia.", "en": "1934 was the hottest year on record worldwide."}, "fakta": {"id": "Tahun 1934 memang sangat panas di Amerika Serikat, tapi di tingkat dunia tahun itu relatif sejuk.", "en": "1934 was very hot in the United States, but it was a relatively cool year globally."}, "question": {"en": "Was 1934 the hottest year in the global record?", "id": "Apakah tahun 1934 merupakan tahun terpanas dalam rekor global?"}, "kw": "1934 terpanas amerika", "thumb": null}, {"slug": "fact-brief-co2data", "fb": true, "date": "7 June 2025", "words": 341, "topic": "warm", "title": {"en": "Fact brief - Are CO2 measurements reliable?", "id": "Fakta singkat - Apakah pengukuran CO2 dapat diandalkan?"}, "claim": {"id": "Pengukuran CO2 di udara tidak bisa dipercaya.", "en": "CO2 measurements can't be trusted."}, "fakta": {"id": "CO2 diukur di banyak tempat oleh lembaga yang berbeda-beda, dengan berbagai alat. Hasilnya cocok satu sama lain.", "en": "CO2 is measured in many places by different agencies and instruments. The results match."}, "question": {"en": "Are CO2 measurements reliable?", "id": "Apakah pengukuran CO2 dapat diandalkan?"}, "kw": "data co2 pengukuran mauna loa dipercaya", "thumb": null}, {"slug": "fact-brief-name", "fb": true, "date": "31 May 2025", "words": 348, "topic": "hoax", "title": {"en": "Fact brief - Was 'global warming' changed to 'climate change' because Earth stopped warming?", "id": "Fakta singkat - Apakah 'pemanasan global' diubah menjadi 'perubahan iklim' karena bumi berhenti melakukan pemanasan?"}, "claim": {"id": "Istilah pemanasan global diganti menjadi perubahan iklim karena Bumi berhenti memanas.", "en": "'Global warming' became 'climate change' because warming stopped."}, "fakta": {"id": "Kedua istilah tetap dipakai dan artinya berbeda. Bumi terus memanas: 10 tahun terakhir (2015 sampai 2024) adalah yang terpanas.", "en": "Both terms are still used and mean different things. Warming continues: 2015 to 2024 were the ten hottest years."}, "question": {"en": "Was 'global warming' changed to 'climate change' because Earth stopped warming?", "id": "Apakah 'pemanasan global' diubah menjadi 'perubahan iklim' karena bumi berhenti melakukan pemanasan?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-green", "fb": true, "date": "17 May 2025", "words": 347, "topic": "warm", "title": {"en": "Fact brief - Did Viking settlers enjoy a warm beach climate in Greenland?", "id": "Fakta singkat - Apakah pemukim Viking menikmati iklim pantai yang hangat di Greenland?"}, "claim": {"id": "Dulu Greenland sangat hangat sampai orang Viking bisa bersantai di pantai.", "en": "Vikings enjoyed a warm beach climate in Greenland."}, "fakta": {"id": "Selatan Greenland memang punya sedikit tanaman saat itu, tapi tidak pernah sehangat daerah pantai tropis. Nama Greenland dipilih untuk menarik pendatang.", "en": "Southern Greenland had some plants then, but it was never beach-warm. The name was chosen to attract settlers."}, "question": {"en": "Did Viking settlers enjoy a warm beach climate in Greenland?", "id": "Apakah pemukim Viking menikmati iklim pantai yang hangat di Greenland?"}, "kw": "greenland viking hijau", "thumb": null}, {"slug": "fact-brief-weather", "fb": true, "date": "10 May 2025", "words": 338, "topic": "hoax", "title": {"en": "Fact brief - Is the climate as unpredictable as the weather?", "id": "Fakta singkat - Apakah iklim sama tidak terduganya dengan cuaca?"}, "claim": {"id": "Iklim sama susahnya ditebak seperti cuaca.", "en": "Climate is as unpredictable as the weather."}, "fakta": {"id": "Cuaca sulit ditebak lebih dari beberapa hari. Iklim adalah pola jangka panjang yang bisa diperkirakan, misalnya dari jumlah gas rumah kaca.", "en": "Weather is hard to forecast beyond a few days. Climate is a long-term pattern that can be projected, for example from greenhouse gas levels."}, "question": {"en": "Is the climate as unpredictable as the weather?", "id": "Apakah iklim tidak dapat diprediksi seperti cuaca?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-oism", "fb": true, "date": "26 April 2025", "words": 381, "topic": "hoax", "title": {"en": "Fact brief - Do the 31,000 signatures of the OISM Petition Project invalidate the scientific consensus on climate change?", "id": "Fakta singkat - Apakah 31.000 tanda tangan Proyek Petisi OISM membatalkan konsensus ilmiah mengenai perubahan iklim?"}, "claim": {"id": "Ada 31.000 ilmuwan yang menandatangani petisi menolak perubahan iklim.", "en": "31,000 scientists signed a petition rejecting climate change."}, "fakta": {"id": "Hanya sekitar 0,1% penanda tangan adalah ahli iklim, dan banyak nama palsu atau tidak bisa diperiksa. Kesepakatan para ahli iklim tetap kuat.", "en": "Only about 0.1% of signers were climate scientists, and many names were fake or unverifiable. Expert consensus stands."}, "question": {"en": "Do the 31,000 signatures of the OISM Petition Project invalidate the scientific consensus on climate change?", "id": "Apakah 31.000 tanda tangan Proyek Petisi OISM membatalkan konsensus ilmiah mengenai perubahan iklim?"}, "kw": "petisi 31000 ilmuwan tanda tangan", "thumb": null}, {"slug": "fact-brief-impacts", "fb": true, "date": "19 April 2025", "words": 383, "topic": "disaster", "title": {"en": "Fact brief - Is climate change a net benefit for society?", "id": "Fakta singkat - Apakah perubahan iklim membawa manfaat bersih bagi masyarakat?"}, "claim": {"id": "Perubahan iklim justru menguntungkan manusia.", "en": "Climate change is good for society."}, "fakta": {"id": "Perubahan iklim lebih banyak merugikan. Antara tahun 2000 dan 2019, kerugian cuaca ekstrem akibat perubahan iklim mencapai 2,86 triliun dolar AS.", "en": "It does far more harm than good. From 2000 to 2019, climate-linked extreme weather caused 2.86 trillion US dollars in damage."}, "question": {"en": "Is climate change a net benefit for society?", "id": "Apakah perubahan iklim memberikan manfaat bersih bagi masyarakat?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-mars", "fb": true, "date": "5 April 2025", "words": 345, "topic": "cause", "title": {"en": "Fact brief - Is Mars warming?", "id": "Fakta singkat - Apakah Mars memanas?"}, "claim": {"id": "Mars juga memanas, jadi penyebabnya matahari, bukan manusia.", "en": "Mars is warming too, so it's the Sun, not people."}, "fakta": {"id": "Iklim Mars berubah karena alasan yang sangat berbeda, misalnya badai debu dan orbitnya. Tidak ada data pemanasan di Mars yang mirip dengan Bumi.", "en": "Mars' climate changes for very different reasons, like dust storms and its orbit. There's no Mars warming trend like Earth's."}, "question": {"en": "Is Mars warming?", "id": "Apakah Mars memanas?"}, "kw": "mars planet", "thumb": null}, {"slug": "fact-brief-waste", "fb": true, "date": "15 March 2025", "words": 341, "topic": "cause", "title": {"en": "Fact brief - Is waste heat from industrial activity the reason the planet is warming?", "id": "Fakta singkat - Apakah limbah panas dari aktivitas industri menjadi penyebab pemanasan global?"}, "claim": {"id": "Bumi panas karena panas buangan dari pabrik dan mesin.", "en": "Waste heat from industry is warming the planet."}, "fakta": {"id": "Panas buangan hanya sekitar 1% dari pemanasan. Pengaruh CO2 sekitar 100 kali lebih besar.", "en": "Waste heat is only about 1% of warming. CO2's effect is about 100 times bigger."}, "question": {"en": "Is waste heat from industrial activity the reason the planet is warming?", "id": "Apakah limbah panas dari aktivitas industri menjadi penyebab pemanasan global?"}, "kw": "panas buangan pabrik mesin", "thumb": null}, {"slug": "fact-brief-greenland", "fb": true, "date": "8 March 2025", "words": 354, "topic": "ocean", "title": {"en": "Fact brief - Is Greenland losing land ice?", "id": "Fakta singkat - Apakah Greenland kehilangan daratan esnya?"}, "claim": {"id": "Greenland tidak kehilangan es.", "en": "Greenland isn't losing ice."}, "fakta": {"id": "Satelit menunjukkan Greenland kehilangan es setiap tahun sejak 1998, dan makin cepat.", "en": "Satellites show Greenland has lost ice every year since 1998, and faster over time."}, "question": {"en": "Is Greenland losing land ice?", "id": "Apakah Greenland kehilangan daratan esnya?"}, "kw": "es greenland mencair", "thumb": null}, {"slug": "fact-brief-pastco2", "fb": true, "date": "1 March 2025", "words": 344, "topic": "cause", "title": {"en": "Fact brief - Are high CO2 levels harmless because they also occurred in the past?", "id": "Fakta singkat - Apakah kadar CO2 yang tinggi tidak berbahaya karena pernah terjadi di masa lalu?"}, "claim": {"id": "CO2 tinggi tidak berbahaya karena dulu juga pernah tinggi.", "en": "High CO2 is harmless because it happened before."}, "fakta": {"id": "Terakhir kali CO2 setinggi sekarang, 3 juta tahun lalu, permukaan laut bisa sampai 25 meter lebih tinggi. Kota dan pertanian kita tidak dibangun untuk kondisi seperti itu.", "en": "The last time CO2 was this high, 3 million years ago, seas were up to 25 metres higher. Our cities and farms weren't built for that."}, "question": {"en": "Are high CO2 levels harmless because they also occurred in the past?", "id": "Apakah kadar CO2 yang tinggi tidak berbahaya karena hal tersebut juga terjadi di masa lalu?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-sealevel", "fb": true, "date": "15 February 2025", "words": 303, "topic": "ocean", "title": {"en": "Fact brief - Is sea level rise exaggerated?", "id": "Fakta singkat - Apakah kenaikan permukaan laut berlebihan?"}, "claim": {"id": "Kenaikan permukaan laut dibesar-besarkan.", "en": "Sea level rise is exaggerated."}, "fakta": {"id": "Permukaan laut terus naik dan makin cepat: lebih dari 20 cm sejak 1880, dan sekitar 10 cm sejak 1993.", "en": "Sea level keeps rising, and faster: over 20 cm since 1880 and about 10 cm since 1993."}, "question": {"en": "Is sea level rise exaggerated?", "id": "Apakah kenaikan permukaan air laut berlebihan?"}, "kw": "air laut naik pantai rob tenggelam pesisir", "thumb": null}, {"slug": "fact-brief-methane", "fb": true, "date": "8 February 2025", "words": 331, "topic": "cause", "title": {"en": "Fact brief - Is methane the largest driver of recent global warming?", "id": "Fakta singkat - Apakah metana merupakan penyebab terbesar pemanasan global saat ini?"}, "claim": {"id": "Metana adalah penyebab utama pemanasan, bukan CO2.", "en": "Methane, not CO2, is the main cause of warming."}, "fakta": {"id": "Metana menyumbang sekitar 20 sampai 30% pemanasan. Penyebab utamanya tetap CO2 dari manusia.", "en": "Methane causes about 20 to 30% of recent warming. Human CO2 is still the main driver."}, "question": {"en": "Is methane the largest driver of recent global warming?", "id": "Apakah metana merupakan penyebab terbesar pemanasan global saat ini?"}, "kw": "metana sapi sawah gas", "thumb": null}, {"slug": "fact-brief-species", "fb": true, "date": "1 February 2025", "words": 365, "topic": "disaster", "title": {"en": "Fact brief - Is global warming promoting biodiversity?", "id": "Fakta singkat - Apakah pemanasan global meningkatkan keanekaragaman hayati?"}, "claim": {"id": "Pemanasan global membuat makhluk hidup makin beragam.", "en": "Global warming increases biodiversity."}, "fakta": {"id": "Keanekaragaman hayati justru menurun. Banyak hewan dan tumbuhan tidak bisa menyesuaikan diri atau pindah cukup cepat.", "en": "Biodiversity is falling. Many species can't adapt or move fast enough."}, "question": {"en": "Is global warming promoting biodiversity?", "id": "Apakah pemanasan global meningkatkan keanekaragaman hayati?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-trace", "fb": true, "date": "18 January 2025", "words": 370, "topic": "cause", "title": {"en": "Fact brief - Can CO2 be ignored because it’s just a trace gas?", "id": "Fakta singkat - Bisakah CO2 diabaikan karena hanya berupa gas sisa?"}, "claim": {"id": "CO2 hanya sedikit di udara, jadi bisa diabaikan.", "en": "CO2 is only a trace gas, so it doesn't matter."}, "fakta": {"id": "Meski jumlahnya kecil, CO2 menahan panas. Tanpa gas rumah kaca, suhu rata-rata Bumi sekitar -18°C.", "en": "Even in small amounts, CO2 traps heat. Without greenhouse gases, Earth would average about -18°C."}, "question": {"en": "Can CO2 be ignored because it’s just a trace gas?", "id": "Bisakah CO2 diabaikan karena hanya berupa gas sisa?"}, "kw": "co2 sedikit jumlah kecil", "thumb": null}, {"slug": "fact-brief-iceage", "fb": true, "date": "21 December 2024", "words": 401, "topic": "warm", "title": {"en": "Fact brief - Are we heading into an 'ice age'?", "id": "Fakta singkat - Apakah kita sedang menuju ke 'zaman es'?"}, "claim": {"id": "Bumi sedang menuju zaman es.", "en": "We're heading into an ice age."}, "fakta": {"id": "Sejak Revolusi Industri Bumi makin panas, bukan makin dingin. Zaman es mengikuti perubahan orbit Bumi yang berlangsung ribuan tahun.", "en": "Earth has warmed since the Industrial Revolution, not cooled. Ice ages follow orbit changes over thousands of years."}, "question": {"en": "Are we heading into an ‘ice age’?", "id": "Apakah kita sedang menuju ke ‘zaman es’?"}, "kw": "zaman es dingin", "thumb": null}, {"slug": "fact-brief-extreme", "fb": true, "date": "23 November 2024", "words": 327, "topic": "disaster", "title": {"en": "Fact brief - Has human-caused climate change increased extreme weather?", "id": "Fakta singkat - Apakah perubahan iklim yang disebabkan oleh manusia telah meningkatkan cuaca ekstrem?"}, "claim": {"id": "Manusia tidak membuat cuaca ekstrem makin sering.", "en": "Humans haven't made extreme weather worse."}, "fakta": {"id": "Gas buang dari manusia membuat gelombang panas, kekeringan, hujan lebat, dan banjir makin sering dan makin parah.", "en": "Human emissions are making heatwaves, droughts, heavy rain and floods more frequent and severe."}, "question": {"en": "Has human-caused climate change increased extreme weather?", "id": "Apakah perubahan iklim yang disebabkan oleh manusia telah meningkatkan cuaca ekstrem?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-consensus", "fb": true, "date": "9 November 2024", "words": 355, "topic": "hoax", "title": {"en": "Fact brief - Is there an expert consensus on human-caused global warming?", "id": "Fakta singkat - Apakah ada konsensus para ahli mengenai pemanasan global yang disebabkan oleh manusia?"}, "claim": {"id": "Para ahli tidak sepakat bahwa manusia menyebabkan pemanasan global.", "en": "Experts don't agree that humans cause global warming."}, "fakta": {"id": "Hampir semua ilmuwan iklim sepakat. Penelitian tahun 2021 menunjukkan kesepakatan sekitar 98 sampai 99%.", "en": "Nearly all climate scientists agree. 2021 studies found about 98 to 99% agreement."}, "question": {"en": "Is there an expert consensus on human-caused global warming?", "id": "Apakah ada konsensus para ahli mengenai pemanasan global yang disebabkan oleh manusia?"}, "kw": "sepakat ilmuwan 97 persen konsensus", "thumb": null}, {"slug": "fact-brief-glacier", "fb": true, "date": "2 November 2024", "words": 341, "topic": "ocean", "title": {"en": "Fact brief - Are most glaciers growing?", "id": "Fakta singkat - Apakah sebagian besar gletser tumbuh?"}, "claim": {"id": "Sebagian besar gletser justru bertambah besar.", "en": "Most glaciers are growing."}, "fakta": {"id": "Hampir semua gletser di dunia terus menyusut. Tahun 2023 adalah tahun ke-36 berturut-turut gletser kehilangan es.", "en": "Nearly all glaciers are shrinking. 2023 was the 36th year in a row of glacier ice loss."}, "question": {"en": "Are most glaciers growing?", "id": "Apakah sebagian besar gletser tumbuh?"}, "kw": "gletser es gunung", "thumb": null}, {"slug": "fact-brief-volcano", "fb": true, "date": "26 October 2024", "words": 339, "topic": "cause", "title": {"en": "Fact brief - Do volcanoes emit more CO2 than humans?", "id": "Fakta singkat - Apakah gunung berapi mengeluarkan lebih banyak CO2 dibandingkan manusia?"}, "claim": {"id": "Gunung berapi mengeluarkan CO2 lebih banyak daripada manusia.", "en": "Volcanoes emit more CO2 than humans."}, "fakta": {"id": "Kegiatan manusia mengeluarkan lebih dari 100 kali lebih banyak CO2 daripada semua gunung berapi setiap tahun.", "en": "Human activity emits more than 100 times as much CO2 as all volcanoes each year."}, "question": {"en": "Do volcanoes emit more CO2 than humans?", "id": "Apakah gunung berapi mengeluarkan lebih banyak CO2 daripada manusia?"}, "kw": "gunung berapi vulkanik merapi letusan", "thumb": null}, {"slug": "fact-brief-plant", "fb": true, "date": "12 October 2024", "words": 413, "topic": "hoax", "title": {"en": "Fact brief - Is more CO2 a good thing because it’s plant food?", "id": "Fakta singkat - Apakah lebih banyak CO2 merupakan hal yang baik karena merupakan makanan nabati?"}, "claim": {"id": "CO2 itu bagus karena menjadi makanan tanaman.", "en": "More CO2 is good because it's plant food."}, "fakta": {"id": "Tanaman memang butuh CO2, tapi panas, kekeringan, dan penyakit akibat perubahan iklim justru bisa menurunkan hasil panen dan gizi makanan.", "en": "Plants need CO2, but heat, drought and disease from climate change can cut harvests and food quality."}, "question": {"en": "Is more CO2 a good thing because it’s plant food?", "id": "Apakah lebih banyak CO2 merupakan hal yang baik karena merupakan makanan nabati?"}, "kw": "tanaman makanan pertanian panen pupuk", "thumb": null}, {"slug": "fact-brief-co2increase", "fb": true, "date": "14 September 2024", "words": 339, "topic": "cause", "title": {"en": "Fact brief - Does manmade CO2 have any detectable fingerprint?", "id": "Fakta singkat - Apakah CO2 buatan manusia mempunyai sidik jari yang dapat dideteksi?"}, "claim": {"id": "Tidak ada bukti bahwa kenaikan CO2 berasal dari manusia.", "en": "There's no evidence rising CO2 comes from humans."}, "fakta": {"id": "Ada sidik jarinya. CO2 dari bahan bakar fosil punya campuran isotop karbon yang khas, dan campuran itulah yang makin banyak di udara.", "en": "There is a fingerprint: fossil fuel CO2 has a distinctive carbon isotope mix, and that mix is growing in the air."}, "question": {"en": "Does manmade CO2 have any detectable fingerprint?", "id": "Apakah CO2 buatan manusia mempunyai sidik jari yang dapat dideteksi?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-cycle", "fb": true, "date": "31 August 2024", "words": 330, "topic": "cause", "title": {"en": "Fact brief - Is recent global warming part of a natural cycle?", "id": "Fakta singkat - Apakah pemanasan global yang terjadi saat ini merupakan bagian dari siklus alami?"}, "claim": {"id": "Pemanasan sekarang hanya siklus alam.", "en": "Today's warming is just a natural cycle."}, "fakta": {"id": "Siklus alam seperti perubahan orbit Bumi sedang dalam fase mendingin. Pemanasan sekarang disebabkan gas rumah kaca dari manusia.", "en": "Natural cycles like Earth's orbit are in a cooling phase. Today's warming comes from human greenhouse gases."}, "question": {"en": "Is recent global warming part of a natural cycle?", "id": "Apakah pemanasan global yang terjadi saat ini merupakan bagian dari siklus alami?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-cosmic", "fb": true, "date": "24 August 2024", "words": 351, "topic": "cause", "title": {"en": "Fact brief - Is decreased cosmic ray activity driving global warming?", "id": "Fakta singkat - Apakah penurunan aktivitas sinar kosmik menyebabkan pemanasan global?"}, "claim": {"id": "Pemanasan global disebabkan oleh berkurangnya sinar kosmik.", "en": "Fewer cosmic rays are causing global warming."}, "fakta": {"id": "Data selama lebih dari 50 tahun tidak menunjukkan bahwa sinar kosmik menyebabkan pemanasan. Penyebab utamanya tetap CO2.", "en": "Over 50 years of data show no evidence that cosmic rays drive warming. CO2 remains the main cause."}, "question": {"en": "Is decreased cosmic ray activity driving global warming?", "id": "Apakah penurunan aktivitas sinar kosmik menyebabkan pemanasan global?"}, "kw": "sinar kosmik", "thumb": null}, {"slug": "fact-brief-correlate", "fb": true, "date": "17 August 2024", "words": 336, "topic": "cause", "title": {"en": "Fact brief - Does CO2 correlate with global temperature long-term?", "id": "Fakta singkat - Apakah CO2 berkorelasi dengan suhu global dalam jangka panjang?"}, "claim": {"id": "CO2 dan suhu Bumi tidak berhubungan.", "en": "CO2 and temperature aren't linked."}, "fakta": {"id": "Dalam jangka panjang, CO2 dan suhu naik bersama. Naik-turun jangka pendek disebabkan hal lain seperti El Niño dan La Niña.", "en": "Over the long term CO2 and temperature rise together. Short-term ups and downs come from things like El Niño and La Niña."}, "question": {"en": "Does CO2 correlate with global temperature long-term?", "id": "Apakah CO2 berkorelasi dengan suhu global dalam jangka panjang?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-co2", "fb": true, "date": "10 August 2024", "words": 339, "topic": "cause", "title": {"en": "Fact brief - Are carbon dioxide emissions from human activities enough to affect the climate?", "id": "Fakta singkat - Apakah emisi karbon dioksida dari aktivitas manusia cukup mempengaruhi iklim?"}, "claim": {"id": "CO2 dari manusia terlalu sedikit untuk mengubah iklim.", "en": "Human CO2 is too small to change the climate."}, "fakta": {"id": "Daratan dan laut tidak mampu menyerap semua tambahan CO2 dari manusia, jadi CO2 di udara terus naik dan mengubah iklim.", "en": "Land and oceans can't absorb all our extra CO2, so it builds up in the air and changes the climate."}, "question": {"en": "Are carbon dioxide emissions from human activities enough to affect the climate?", "id": "Apakah emisi karbon dioksida dari aktivitas manusia cukup mempengaruhi iklim?"}, "kw": "", "thumb": null}, {"slug": "fact-brief-bear", "fb": true, "date": "27 July 2024", "words": 383, "topic": "ocean", "title": {"en": "Fact brief - Are polar bears endangered?", "id": "Fakta singkat - Apakah beruang kutub terancam punah?"}, "claim": {"id": "Beruang kutub tidak terancam.", "en": "Polar bears aren't under threat."}, "fakta": {"id": "Beruang kutub tergolong rentan. Kalau emisi terus naik, sebagian besar populasinya bisa punah pada tahun 2100 karena es tempat mereka berburu mencair.", "en": "Polar bears are classed as vulnerable. If emissions continue, most populations could vanish by 2100 as their hunting ice melts."}, "question": {"en": "Are polar bears endangered?", "id": "Apakah beruang kutub terancam punah?"}, "kw": "beruang kutub hewan", "thumb": null}, {"slug": "fact-brief-climategate", "fb": true, "date": "13 July 2024", "words": 324, "topic": "hoax", "title": {"en": "Fact brief - Were scientists caught falsifying data in the hacked emails incident dubbed 'climategate'?", "id": "Fakta singkat - Apakah para ilmuwan kedapatan memalsukan data dalam insiden peretasan email yang dijuluki 'climategate'?"}, "claim": {"id": "Email ilmuwan yang bocor (Climategate) membuktikan data iklim dipalsukan.", "en": "Leaked emails ('Climategate') proved scientists faked data."}, "fakta": {"id": "Sembilan penyelidikan terpisah menemukan para ilmuwan tidak memalsukan data. Kalimat yang dipermasalahkan ternyata soal cara menggabungkan data.", "en": "Nine separate investigations found no data were faked. The quoted phrases were about how data sets were combined."}, "question": {"en": "Were scientists caught falsifying data in the hacked emails incident dubbed 'climategate'?", "id": "Apakah para ilmuwan kedapatan memalsukan data dalam insiden peretasan email yang dijuluki 'climategate'?"}, "kw": "climategate email bocor data palsu", "thumb": "images/fact-brief-climategate/50052fab45.webp"}, {"slug": "fact-brief-lag", "fb": true, "date": "29 June 2024", "words": 347, "topic": "cause", "title": {"en": "Fact Brief - Does temperature have to rise before CO2 does?", "id": "Fakta Singkat - Apakah suhu harus naik sebelum CO2 naik?"}, "claim": {"id": "Suhu naik dulu baru CO2, jadi CO2 bukan penyebab.", "en": "Temperature rises before CO2, so CO2 isn't the cause."}, "fakta": {"id": "Di masa lalu, pemanasan kadang dimulai oleh perubahan orbit Bumi, lalu CO2 ikut memperkuatnya. Pemanasan sekarang dimulai oleh CO2 dari manusia.", "en": "In the past, orbit changes sometimes started warming and CO2 then amplified it. Today's warming is started by human CO2."}, "question": {"en": "Does temperature have to rise before CO2 does?", "id": "Apakah suhu harus naik sebelum CO2 naik?"}, "kw": "", "thumb": "images/fact-brief-lag/50052fab45.webp"}, {"slug": "fact-brief-mwp", "fb": true, "date": "22 June 2024", "words": 357, "topic": "warm", "title": {"en": "Fact Brief - Was the Medieval Warm Period a global event?", "id": "Fakta Singkat - Apakah Periode Hangat Abad Pertengahan merupakan peristiwa global?"}, "claim": {"id": "Zaman Hangat Abad Pertengahan dulu melanda seluruh dunia.", "en": "The Medieval Warm Period was global."}, "fakta": {"id": "Masa hangat sekitar tahun 950 sampai 1250 hanya terjadi di sebagian belahan Bumi utara. Sekarang, suhu rata-rata dunia sekitar 1°C lebih tinggi daripada masa itu.", "en": "The warm period around 950 to 1250 was limited to parts of the Northern Hemisphere. Global temperatures today are about 1°C higher."}, "question": {"en": "Was the Medieval Warm Period a global event?", "id": "Apakah Periode Hangat Abad Pertengahan merupakan peristiwa global?"}, "kw": "", "thumb": "images/fact-brief-mwp/50052fab45.webp"}, {"slug": "fact-brief-acid-2", "fb": true, "date": "15 June 2024", "words": 332, "topic": "ocean", "title": {"en": "Fact Brief - Is ocean acidification from human activities enough to impact marine ecosystems?", "id": "Fakta Singkat - Apakah pengasaman laut akibat aktivitas manusia cukup berdampak pada ekosistem laut?"}, "claim": {"id": "Laut yang makin asam tidak berpengaruh pada makhluk laut.", "en": "Ocean acidification doesn't affect sea life."}, "fakta": {"id": "CO2 dari manusia membuat laut lebih asam, sehingga kerang, karang, dan plankton sulit membentuk cangkang dan kerangka.", "en": "Human CO2 makes the sea more acidic, so shellfish, coral and plankton struggle to build shells and skeletons."}, "question": {"en": "Is ocean acidification from human activities enough to impact marine ecosystems?", "id": "Apakah pengasaman laut akibat aktivitas manusia cukup berdampak pada ekosistem laut?"}, "kw": "asam laut kerang karang ikan", "thumb": null}, {"slug": "fact-brief-acid-1", "fb": true, "date": "8 June 2024", "words": 310, "topic": "ocean", "title": {"en": "Fact Brief - Is the ocean acidifying?", "id": "Fakta Singkat - Apakah lautan menjadi asam?"}, "claim": {"id": "Laut tidak menjadi asam karena pH-nya masih di atas 7.", "en": "The ocean isn't acidifying because its pH is above 7."}, "fakta": {"id": "Pengasaman artinya pH turun dari biasanya. Walaupun masih di atas 7, pH laut sudah turun dari 8,2 menjadi 8,1 sejak Revolusi Industri.", "en": "Acidification means pH dropping from normal. Ocean pH fell from 8.2 to 8.1 since the Industrial Revolution."}, "question": {"en": "Is the ocean acidifying?", "id": "Apakah lautan menjadi asam?"}, "kw": "asam laut ph kerang", "thumb": null}, {"slug": "fact-brief-model", "fb": true, "date": "1 June 2024", "words": 331, "topic": "hoax", "title": {"en": "Fact Brief - Have climate models overestimated global warming?", "id": "Fakta Singkat - Apakah model iklim melebih-lebihkan pemanasan global?"}, "claim": {"id": "Model iklim melebih-lebihkan pemanasan.", "en": "Climate models overestimate warming."}, "fakta": {"id": "Model iklim sejak tahun 1970-an sudah memperkirakan pemanasan dengan tepat.", "en": "Climate models since the 1970s have predicted warming accurately."}, "question": {"en": "Have climate models overestimated global warming?", "id": "Apakah model iklim melebih-lebihkan pemanasan global?"}, "kw": "model prediksi komputer", "thumb": "images/fact-brief-model/50052fab45.webp"}, {"slug": "fact-brief-breath", "fb": true, "date": "18 May 2024", "words": 338, "topic": "cause", "title": {"en": "Fact Brief - Does breathing contribute to CO2 buildup in the atmosphere?", "id": "Fakta Singkat - Apakah pernapasan berkontribusi terhadap penumpukan CO2 di atmosfer?"}, "claim": {"id": "Napas manusia ikut menambah CO2 di udara.", "en": "Human breathing adds to CO2 in the air."}, "fakta": {"id": "CO2 dari napas berasal dari makanan yang baru saja menyerap CO2 dari udara, jadi seimbang. Yang menambah CO2 adalah pembakaran bahan bakar fosil.", "en": "Breathed-out CO2 comes from food that recently absorbed it, so it balances out. Burning fossil fuels is what adds CO2."}, "question": {"en": "Does breathing contribute to CO2 buildup in the atmosphere?", "id": "Apakah pernapasan berkontribusi terhadap penumpukan CO2 di atmosfer?"}, "kw": "napas bernapas manusia hewan", "thumb": "images/fact-brief-breath/50052fab45.webp"}, {"slug": "fact-brief-antarctica", "fb": true, "date": "27 April 2024", "words": 317, "topic": "ocean", "title": {"en": "Fact Brief - Is Antarctica gaining land ice?", "id": "Fakta Singkat - Apakah Antartika mendapatkan daratan es?"}, "claim": {"id": "Es di daratan Antartika bertambah.", "en": "Antarctica is gaining land ice."}, "fakta": {"id": "Es laut di sekitar Antartika memang naik-turun setiap musim, tapi es di daratannya terus mencair makin cepat.", "en": "Sea ice around Antarctica rises and falls each season, but its land ice keeps melting faster."}, "question": {"en": "Is Antarctica gaining land ice?", "id": "Apakah Antartika mendapatkan daratan es?"}, "kw": "es antartika mencair", "thumb": "images/fact-brief-antarctica/50052fab45.webp"}, {"slug": "fact-brief-1998", "fb": true, "date": "13 April 2024", "words": 281, "topic": "warm", "title": {"en": "Fact Brief - Did global warming stop in 1998?", "id": "Fakta Singkat - Apakah pemanasan global berhenti pada tahun 1998?"}, "claim": {"id": "Pemanasan global berhenti sejak tahun 1998.", "en": "Global warming stopped in 1998."}, "fakta": {"id": "Tahun 1998 panas karena El Niño kuat. Setelah itu suhu terus naik: sepuluh tahun terpanas semuanya terjadi sejak 2010.", "en": "1998 was hot because of a strong El Niño. Warming continued: the ten hottest years have all been since 2010."}, "question": {"en": "Did global warming stop in 1998?", "id": "Apakah pemanasan global berhenti pada tahun 1998?"}, "kw": "1998 berhenti el nino", "thumb": "images/fact-brief-1998/50052fab45.webp"}, {"slug": "social-media-warning-signs-wording-in-posts-and-comments", "fb": false, "date": "14 June 2024", "words": 842, "topic": "hoax", "title": {"en": "Of red flags and warning signs in comments on social media", "id": "Tentang bendera merah dan tanda peringatan dalam komentar di media sosial"}, "intinya": {"id": "Tim Skeptical Science mengumpulkan tanda-tanda bahaya pada komentar di media sosial yang menyangkal perubahan iklim, misalnya mengulang-ulang slogan, menuduh ilmuwan menipu, atau menyerang pribadi. Tanda-tanda ini membantu kita berhenti sejenak sebelum percaya. Daftar lengkapnya ada di gambar berbahasa Inggris.", "en": "Skeptical Science lists red flags in social media comments that deny climate change, such as repeated slogans, accusing scientists of fraud or personal attacks. The full list is in the English image."}, "kw": "media sosial komentar hoaks tanda", "thumb": "images/social-media-warning-signs-wording-in-posts-and-comments/71e1ebba32.webp"}, {"slug": "at-a-glance-runaway", "fb": false, "date": "11 June 2024", "words": 1258, "topic": "warm", "title": {"en": "At a glance - Does positive feedback necessarily mean runaway warming?", "id": "Sekilas - Apakah tanggapan positif berarti pemanasan yang tak terkendali?"}, "intinya": {"id": "Pemanasan memang bisa diperkuat oleh reaksi alam, misalnya es mencair. Tapi bukti dari masa lalu menunjukkan Bumi sangat kecil kemungkinannya mengalami pemanasan yang lepas kendali seperti Venus. Ini bukan alasan untuk santai, karena pemanasan sekarang sudah berbahaya.", "en": "Warming can be amplified by feedbacks like melting ice, but past evidence shows Earth is very unlikely to enter a Venus-style runaway. That's no reason to relax: current warming is already dangerous."}, "kw": "lepas kendali venus", "thumb": "images/at-a-glance-runaway/6e7bc45f06.webp"}, {"slug": "at-a-glance-driver", "fb": false, "date": "4 June 2024", "words": 1234, "topic": "cause", "title": {"en": "At a glance - CO2 is the main driver of climate change", "id": "Sekilas – CO2 adalah penyebab utama perubahan iklim"}, "intinya": {"id": "Tidak ada ilmuwan yang bilang CO2 satu-satunya penyebab perubahan iklim. Ilmu iklim mempelajari semua faktor, dari matahari sampai gunung berapi. Tapi dari semua itu, CO2 dari manusia adalah penyebab utama pemanasan saat ini.", "en": "No scientist says CO2 is the only driver of climate. Climate science studies every factor, from the Sun to volcanoes, and human CO2 is the main driver of today's warming."}, "kw": "penyebab co2 faktor", "thumb": "images/at-a-glance-driver/9ca104ad09.webp"}, {"slug": "at-a-glance-hurricane", "fb": false, "date": "28 May 2024", "words": 1227, "topic": "disaster", "title": {"en": "At a glance - What is the link between hurricanes and global warming?", "id": "Sekilas – Apa hubungan antara badai dan pemanasan global?"}, "intinya": {"id": "Badai tropis mendapat tenaga dari laut yang hangat. Karena laut makin panas, badai yang terkuat bisa makin kuat dan membawa lebih banyak hujan. Artikel ini menjelaskan cara badai terbentuk dengan bahasa sehari-hari.", "en": "Tropical cyclones draw energy from warm seas. As oceans warm, the strongest storms can get stronger and wetter. This piece explains in plain terms how they form."}, "kw": "badai topan siklon", "thumb": "images/at-a-glance-hurricane/967eddda9b.webp"}, {"slug": "at-a-glance-weather", "fb": false, "date": "23 April 2024", "words": 1190, "topic": "warm", "title": {"en": "At a glance - The difference between weather and climate", "id": "Sekilas - Perbedaan cuaca dan iklim"}, "intinya": {"id": "Cuaca hanya bisa diramal dengan baik untuk beberapa hari ke depan. Iklim berbeda: iklim adalah pola rata-rata selama puluhan tahun, yang bisa diperkirakan dari hal-hal besar seperti jumlah gas rumah kaca. Jadi sulitnya meramal cuaca tidak berarti iklim tidak bisa diperkirakan.", "en": "Weather can only be forecast well a few days ahead. Climate is the average pattern over decades, which can be projected from big drivers like greenhouse gases. Hard weather forecasts don't mean climate can't be projected."}, "kw": "cuaca iklim ramalan prakiraan bmkg", "thumb": "images/at-a-glance-weather/c03e3def3e.webp"}, {"slug": "at-a-glance-settled", "fb": false, "date": "16 April 2024", "words": 1152, "topic": "hoax", "title": {"en": "At a glance - Is the science settled?", "id": "Sekilas – Apakah ilmu pengetahuan sudah mapan?"}, "intinya": {"id": "Ilmu pengetahuan terus berkembang. Hal-hal dasar tentang iklim sudah pasti, misalnya CO2 menahan panas dan permukaan laut naik saat es mencair. Yang masih diteliti adalah detailnya, misalnya kapan tepatnya sebuah kota pantai akan terdampak.", "en": "Science keeps developing. The basics of climate are settled, such as CO2 trapping heat and seas rising as ice melts. What's still researched is the detail, like exactly when a coastal town will be affected."}, "kw": "sains pasti ilmuwan debat", "thumb": "images/at-a-glance-settled/4025158c05.webp"}, {"slug": "at-a-glance-elnino", "fb": false, "date": "2 April 2024", "words": 1162, "topic": "elnino", "title": {"en": "At a glance - Global warming and the El Niño Southern Oscillation", "id": "Sekilas - Pemanasan global dan El Niño Southern Oscillation"}, "intinya": {"id": "El Niño dan La Niña hanya memindahkan panas antara laut dan udara, tidak menambah atau mengurangi panas Bumi secara keseluruhan. Jadi El Niño bisa membuat satu tahun lebih panas, tapi tidak bisa menjelaskan pemanasan selama puluhan tahun.", "en": "El Niño and La Niña only move heat between ocean and air; they don't add or remove heat overall. El Niño can make one year hotter but can't explain decades of warming."}, "kw": "el nino la nina", "thumb": "images/at-a-glance-elnino/6b6a9eeaee.webp"}, {"slug": "at-a-glance-albedo", "fb": false, "date": "12 March 2024", "words": 1131, "topic": "ocean", "title": {"en": "At a glance - The albedo effect and global warming", "id": "Sekilas - Efek Albedo dan Pemanasan Global"}, "intinya": {"id": "Albedo adalah seberapa banyak cahaya matahari dipantulkan oleh permukaan, seperti baju putih yang lebih sejuk daripada baju hitam. Saat es mencair, laut yang gelap menyerap lebih banyak panas dan membuat es makin cepat mencair. Ini akibat pemanasan, bukan penyebab awalnya.", "en": "Albedo is how much sunlight a surface reflects, like a white shirt staying cooler than a black one. When ice melts, dark ocean absorbs more heat and speeds up melting. This is a result of warming, not its cause."}, "kw": "albedo es pantul putih", "thumb": "images/at-a-glance-albedo/f48f6ef712.webp"}, {"slug": "at-a-glance-venus", "fb": false, "date": "30 January 2024", "words": 1177, "topic": "cause", "title": {"en": "At a glance - The runaway greenhouse effect on Venus", "id": "Sekilas - Efek rumah kaca yang tak terkendali di Venus"}, "intinya": {"id": "Venus dan Bumi berawal mirip, tapi Venus menjadi sangat panas karena atmosfernya penuh CO2 dan efek rumah kacanya lepas kendali. Artikel ini menjelaskan mengapa jalan kedua planet ini berbeda.", "en": "Venus and Earth started out similar, but Venus became extremely hot because its atmosphere is full of CO2 and its greenhouse effect ran away. This explains why the two planets diverged."}, "kw": "venus planet", "thumb": "images/at-a-glance-venus/7d58a5b569.webp"}, {"slug": "at-a-glance-saturate", "fb": false, "date": "9 January 2024", "words": 1079, "topic": "cause", "title": {"en": "At a glance - Is the CO2 effect saturated?", "id": "Sekilas – Apakah efek CO2 sudah jenuh?"}, "intinya": {"id": "Ada kabar bahwa CO2 sudah jenuh, jadi tambahan CO2 tidak menambah panas. Itu keliru. CO2 tidak seperti kain pel yang penuh air: ia terus menyerap dan melepas panas, jadi makin banyak CO2 tetap membuat Bumi makin hangat.", "en": "Some claim CO2's effect is 'saturated', so more CO2 adds no heat. That's wrong: CO2 isn't like a full mop, it keeps absorbing and re-emitting heat, so more CO2 still means more warming."}, "kw": "co2 jenuh", "thumb": "images/at-a-glance-saturate/100e1293cc.webp"}, {"slug": "at-a-glance-plant", "fb": false, "date": "2 January 2024", "words": 934, "topic": "hoax", "title": {"en": "At a glance - Plants cannot live on CO2 alone", "id": "Sekilas – Tumbuhan tidak bisa hidup hanya dengan CO2"}, "intinya": {"id": "Tanaman memang butuh CO2, tapi juga butuh tanah yang subur, air, dan unsur hara. Tambahan CO2 saja tidak membuat panen lebih baik, apalagi kalau cuaca makin panas dan kering.", "en": "Plants need CO2, but also fertile soil, water and nutrients. Extra CO2 alone doesn't mean better harvests, especially as weather gets hotter and drier."}, "kw": "tanaman makanan pupuk panen", "thumb": "images/at-a-glance-plant/2565084df6.webp"}];
const GLOSS=[{"key": "pemanasan-global", "id": "Pemanasan global", "en": "Global warming", "matchId": ["pemanasan global"], "matchEn": ["global warming"], "defId": "Suhu rata-rata Bumi naik dari tahun ke tahun. Penyebab utamanya adalah kegiatan manusia.", "defEn": "Earth's average temperature rising year after year, mainly because of human activity."}, {"key": "perubahan-iklim", "id": "Perubahan iklim", "en": "Climate change", "matchId": ["perubahan iklim"], "matchEn": ["climate change"], "defId": "Pola cuaca dalam waktu lama (puluhan tahun) ikut berubah: suhu, hujan, dan musim.", "defEn": "Long-term changes (over decades) in weather patterns: temperature, rain and seasons."}, {"key": "cuaca-iklim", "id": "Cuaca dan iklim", "en": "Weather and climate", "matchId": ["cuaca"], "matchEn": ["weather"], "defId": "Cuaca adalah keadaan udara hari ini, misalnya hujan atau panas. Iklim adalah kebiasaan cuaca di suatu tempat selama puluhan tahun.", "defEn": "Weather is what the air is like today, like rain or heat. Climate is the usual weather of a place over decades."}, {"key": "gas-rumah-kaca", "id": "Gas rumah kaca", "en": "Greenhouse gas", "matchId": ["gas rumah kaca", "efek rumah kaca"], "matchEn": ["greenhouse gas", "greenhouse gases", "greenhouse effect"], "defId": "Gas di udara yang menahan panas, seperti selimut yang menutupi Bumi. Contohnya karbon dioksida (CO2) dan metana.", "defEn": "Gases in the air that trap heat, like a blanket around Earth. Examples: carbon dioxide (CO2) and methane."}, {"key": "co2", "id": "CO2 (karbon dioksida)", "en": "CO2 (carbon dioxide)", "matchId": ["CO2", "karbon dioksida"], "matchEn": ["CO2", "carbon dioxide"], "defId": "Gas yang keluar saat kita membakar bensin, solar, batu bara, atau kayu. Gas ini membuat Bumi makin panas.", "defEn": "The gas released when we burn petrol, diesel, coal or wood. It makes Earth warmer."}, {"key": "fosil", "id": "Bahan bakar fosil", "en": "Fossil fuels", "matchId": ["bahan bakar fosil"], "matchEn": ["fossil fuels", "fossil fuel"], "defId": "Batu bara, minyak bumi (bensin, solar), dan gas alam. Terbentuk dari sisa makhluk hidup jutaan tahun lalu.", "defEn": "Coal, oil (petrol, diesel) and natural gas, formed from living things millions of years ago."}, {"key": "emisi", "id": "Emisi", "en": "Emissions", "matchId": ["emisi"], "matchEn": ["emissions"], "defId": "Gas buang yang dilepas ke udara, misalnya dari knalpot, pabrik, atau pembangkit listrik.", "defEn": "Waste gases released into the air, for example from exhaust pipes, factories or power plants."}, {"key": "elnino", "id": "El Niño", "en": "El Niño", "matchId": ["El Niño", "El Nino"], "matchEn": ["El Niño", "El Nino"], "defId": "Saat laut di tengah Samudra Pasifik lebih hangat dari biasanya. Di Indonesia, El Niño sering membuat musim kemarau lebih kering dan lebih panjang.", "defEn": "When the central Pacific Ocean is warmer than usual. In Indonesia it often brings a drier, longer dry season."}, {"key": "lanina", "id": "La Niña", "en": "La Niña", "matchId": ["La Niña", "La Nina"], "matchEn": ["La Niña", "La Nina"], "defId": "Kebalikan El Niño: laut di tengah Samudra Pasifik lebih dingin dari biasanya. Di Indonesia, La Niña sering membawa lebih banyak hujan.", "defEn": "The opposite of El Niño. In Indonesia it often brings more rain."}, {"key": "gelombang-panas", "id": "Gelombang panas", "en": "Heatwave", "matchId": ["gelombang panas"], "matchEn": ["heatwave", "heat wave", "heatwaves"], "defId": "Beberapa hari berturut-turut yang jauh lebih panas dari biasanya. Bisa berbahaya untuk kesehatan, terutama bagi orang tua dan anak kecil.", "defEn": "Several days in a row that are much hotter than normal. Dangerous for health, especially for older people and small children."}, {"key": "pra-industri", "id": "Masa pra-industri", "en": "Pre-industrial", "matchId": ["pra-industri", "praindustri"], "matchEn": ["pre-industrial", "preindustrial"], "defId": "Masa sebelum ada banyak pabrik dan mesin, sekitar tahun 1850 sampai 1900. Sering dipakai sebagai patokan untuk mengukur kenaikan suhu.", "defEn": "The time before many factories and machines, around 1850 to 1900. Used as the starting point to measure warming."}, {"key": "ppm", "id": "ppm", "en": "ppm", "matchId": ["ppm"], "matchEn": ["ppm"], "defId": "Singkatan dari “bagian per sejuta”. Contoh: 420 ppm CO2 artinya ada 420 bagian CO2 di setiap sejuta bagian udara.", "defEn": "Short for “parts per million”. 420 ppm CO2 means 420 parts CO2 in every million parts of air."}, {"key": "konspirasi", "id": "Teori konspirasi", "en": "Conspiracy theory", "matchId": ["teori konspirasi"], "matchEn": ["conspiracy theory", "conspiracy theories"], "defId": "Cerita yang menuduh ada kelompok rahasia yang sengaja mengatur sesuatu, tanpa bukti yang kuat.", "defEn": "A story claiming a secret group is controlling something on purpose, without strong evidence."}, {"key": "panel-surya", "id": "Panel surya", "en": "Solar panel", "matchId": ["panel surya"], "matchEn": ["solar panels", "solar panel"], "defId": "Papan yang mengubah cahaya matahari menjadi listrik.", "defEn": "A panel that turns sunlight into electricity."}, {"key": "atmosfer", "id": "Atmosfer", "en": "Atmosphere", "matchId": ["atmosfer"], "matchEn": ["atmosphere"], "defId": "Lapisan udara yang menyelimuti Bumi.", "defEn": "The layer of air around Earth."}, {"key": "uap-air", "id": "Uap air", "en": "Water vapour", "matchId": ["uap air"], "matchEn": ["water vapor", "water vapour"], "defId": "Air dalam bentuk gas di udara. Tidak kelihatan, tapi bisa menjadi awan dan hujan.", "defEn": "Water as a gas in the air. Invisible, but it becomes clouds and rain."}, {"key": "curah-hujan", "id": "Curah hujan", "en": "Rainfall", "matchId": ["curah hujan"], "matchEn": ["rainfall", "precipitation"], "defId": "Banyaknya air hujan yang turun di suatu tempat, biasanya diukur dalam milimeter.", "defEn": "How much rain falls in a place, usually measured in millimetres."}, {"key": "kekeringan", "id": "Kekeringan", "en": "Drought", "matchId": ["kekeringan"], "matchEn": ["drought", "droughts"], "defId": "Masa panjang dengan hujan jauh lebih sedikit dari biasanya, sehingga air untuk minum, sawah, dan ternak berkurang.", "defEn": "A long period with much less rain than usual, so there is less water for drinking, crops and animals."}, {"key": "dekade", "id": "Dekade", "en": "Decade", "matchId": ["dekade"], "matchEn": ["decade", "decades"], "defId": "Masa sepuluh tahun.", "defEn": "Ten years."}, {"key": "konsensus", "id": "Konsensus", "en": "Consensus", "matchId": ["konsensus"], "matchEn": ["consensus"], "defId": "Kesepakatan hampir semua ahli.", "defEn": "Agreement among almost all experts."}, {"key": "inframerah", "id": "Radiasi inframerah", "en": "Infrared radiation", "matchId": ["radiasi inframerah", "inframerah"], "matchEn": ["infrared"], "defId": "Panas yang dipancarkan benda. Tidak terlihat mata, tapi terasa, seperti hangat dari aspal di siang hari.", "defEn": "Heat given off by things. You can't see it but you can feel it, like warmth from a road at midday."}, {"key": "isotop", "id": "Isotop", "en": "Isotope", "matchId": ["isotop"], "matchEn": ["isotope"], "defId": "Jenis atom dari unsur yang sama dengan berat sedikit berbeda. Ilmuwan memakainya seperti sidik jari untuk tahu asal karbon di udara.", "defEn": "Versions of the same atom with slightly different weight. Scientists use them like a fingerprint to trace where carbon came from."}, {"key": "kendaraan-listrik", "id": "Kendaraan listrik", "en": "Electric vehicle", "matchId": ["kendaraan listrik", "mobil listrik"], "matchEn": ["electric vehicles", "electric vehicle", "EVs", "EV"], "defId": "Mobil atau motor yang berjalan dengan baterai, bukan bensin.", "defEn": "A car or motorbike that runs on a battery instead of petrol."}, {"key": "terbarukan", "id": "Energi terbarukan", "en": "Renewable energy", "matchId": ["energi terbarukan"], "matchEn": ["renewable energy", "renewables"], "defId": "Energi dari sumber yang tidak habis, seperti matahari, angin, dan air.", "defEn": "Energy from sources that don't run out, like sun, wind and water."}, {"key": "zaman-es-kecil", "id": "Zaman Es Kecil", "en": "Little Ice Age", "matchId": ["Zaman Es Kecil"], "matchEn": ["Little Ice Age"], "defId": "Masa lebih dingin sekitar tahun 1350 sampai 1850, terutama di Eropa dan Amerika Utara.", "defEn": "A cooler period around 1350 to 1850, mainly in Europe and North America."}, {"key": "muka-laut", "id": "Kenaikan permukaan laut", "en": "Sea level rise", "matchId": ["permukaan air laut", "permukaan laut"], "matchEn": ["sea level", "sea levels"], "defId": "Air laut makin tinggi karena es di daratan mencair dan air laut memuai saat panas. Daerah pesisir jadi lebih mudah banjir.", "defEn": "The sea gets higher because land ice melts and warm water expands. Coasts flood more easily."}, {"key": "terumbu", "id": "Terumbu karang", "en": "Coral reef", "matchId": ["terumbu karang"], "matchEn": ["coral reef", "coral reefs"], "defId": "Karang di laut dangkal yang menjadi rumah bagi banyak ikan. Karang bisa memutih dan mati kalau laut terlalu panas.", "defEn": "Coral in shallow seas that is home to many fish. It can bleach and die when the sea is too hot."}, {"key": "asam", "id": "Laut makin asam", "en": "Ocean acidification", "matchId": ["pengasaman laut", "lebih asam"], "matchEn": ["acidification", "more acidic"], "defId": "CO2 dari udara larut ke laut dan membuat air laut lebih asam. Kerang dan karang jadi sulit membentuk cangkang dan kerangka.", "defEn": "CO2 dissolves into the sea and makes it more acidic, so shellfish and coral struggle to build shells and skeletons."}, {"key": "pusat-data", "id": "Pusat data", "en": "Data centre", "matchId": ["pusat data"], "matchEn": ["data center", "data centers", "data centres"], "defId": "Gedung besar berisi ribuan komputer yang menjalankan internet dan AI. Butuh listrik dan air pendingin yang sangat banyak.", "defEn": "A big building full of computers that run the internet and AI. It needs a lot of electricity and cooling water."}, {"key": "siklon", "id": "Siklon tropis", "en": "Tropical cyclone", "matchId": ["siklon tropis"], "matchEn": ["tropical cyclone", "tropical cyclones", "hurricane", "hurricanes"], "defId": "Badai besar berputar yang terbentuk di atas laut hangat. Di Amerika disebut hurricane, di Asia Timur disebut topan.", "defEn": "A huge spinning storm that forms over warm sea. Called a hurricane in America and a typhoon in East Asia."}, {"key": "ipcc", "id": "IPCC", "en": "IPCC", "matchId": ["IPCC"], "matchEn": ["IPCC"], "defId": "Panel ilmuwan dunia di bawah PBB yang merangkum penelitian tentang perubahan iklim.", "defEn": "A UN panel of scientists that summarises climate change research."}, {"key": "wmo", "id": "WMO", "en": "WMO", "matchId": ["WMO"], "matchEn": ["WMO"], "defId": "Organisasi Meteorologi Dunia, badan PBB untuk cuaca, iklim, dan air.", "defEn": "The World Meteorological Organization, the UN agency for weather, climate and water."}, {"key": "anomali", "id": "Anomali suhu", "en": "Temperature anomaly", "matchId": ["anomali"], "matchEn": ["anomaly", "anomalies"], "defId": "Selisih suhu dibanding rata-rata biasanya. Anomali +1°C artinya 1°C lebih panas dari biasanya.", "defEn": "The difference from the usual average. An anomaly of +1°C means 1°C hotter than normal."}, {"key": "siklus-hidup", "id": "Siklus hidup", "en": "Lifecycle", "matchId": ["siklus hidup", "seumur hidup"], "matchEn": ["lifecycle", "lifetime"], "defId": "Seluruh umur sebuah barang, dari bahan mentah, pembuatan, pemakaian, sampai dibuang.", "defEn": "A product's whole life, from raw materials and manufacture to use and disposal."}, {"key": "metana", "id": "Metana", "en": "Methane", "matchId": ["metana"], "matchEn": ["methane"], "defId": "Gas rumah kaca yang kuat. Keluar dari sawah, ternak, sampah, dan kebocoran gas alam.", "defEn": "A strong greenhouse gas from rice fields, livestock, rubbish and gas leaks."}, {"key": "acre", "id": "Acre", "en": "Acre", "matchId": ["acre"], "matchEn": ["acre", "acres"], "defId": "Satuan luas yang dipakai di Amerika. Satu acre kira-kira 0,4 hektar, atau kira-kira setengah lapangan sepak bola.", "defEn": "A US unit of area, about 0.4 hectares."}, {"key": "pemutihan-karang", "id": "Pemutihan karang", "en": "Coral bleaching", "matchId": ["pemutihan karang"], "matchEn": ["coral bleaching", "bleaching"], "defId": "Saat laut terlalu panas, karang mengusir ganggang kecil yang memberinya makan dan warna. Karang jadi putih dan bisa mati kalau air tidak cepat dingin.", "defEn": "When the sea is too hot, coral expels the tiny algae that feed and colour it. It turns white and may die."}, {"key": "air-tanah", "id": "Air tanah", "en": "Groundwater", "matchId": ["air tanah"], "matchEn": ["groundwater"], "defId": "Air yang tersimpan di dalam tanah dan batuan, yang kita ambil lewat sumur dan pompa.", "defEn": "Water stored underground in soil and rock, drawn up by wells and pumps."}, {"key": "albedo", "id": "Albedo", "en": "Albedo", "matchId": ["albedo"], "matchEn": ["albedo"], "defId": "Seberapa banyak cahaya matahari yang dipantulkan sebuah permukaan. Es dan salju memantulkan banyak cahaya, laut dan aspal menyerap banyak panas.", "defEn": "How much sunlight a surface reflects. Ice reflects a lot; ocean and asphalt absorb a lot."}, {"key": "prebunking", "id": "Prebunking", "en": "Prebunking", "matchId": ["prebunking"], "matchEn": ["prebunking", "prebunk"], "defId": "Memberi tahu orang lebih dulu tentang trik yang biasa dipakai untuk menyebar kabar bohong, supaya mereka tidak mudah tertipu.", "defEn": "Warning people in advance about common misinformation tricks so they aren't fooled."}];
